/** Topic tours. Read-only previews of real forms: no submit/click/identity mutation. */
function melkinoTourLatestPropertyUrl(): string
{
    static $url;
    if ($url !== null) return $url;
    $url = '';
    global $pdo;
    if (!($pdo instanceof PDO)) return $url;
    try {
        $id = $pdo->query("SELECT id FROM ads WHERE status = 'published' ORDER BY COALESCE(published_at, created_at) DESC, id DESC LIMIT 1")->fetchColumn();
        if ($id !== false && (string)$id !== '') {
            // Legacy schema uses AD-* string IDs. Never cast them to an integer.
            $url = 'property-details.php?id=' . rawurlencode((string)$id) . '&legacy=1';
        }
    } catch (Throwable $e) { /* empty/error: show an explanatory step, never redirect in a loop */ }
    return $url;
}

